from random import randint, seed
import pandas as pd

# Method
def task_func(goals, penalties, rng_seed=None):
    """
    Build a DataFrame with columns:
      - Team
      - Match Result

    `goals` and `penalties` can be scalars or iterable collections.
    If an element is a 2-item integer tuple/list, it is interpreted as
    an inclusive random range and sampled with randint.
    Penalties are converted into fines using a predefined cost.
    """
    PREDEFINED_FINE_COST = 100

    if rng_seed is not None:
        seed(rng_seed)

    def _to_list(value):
        if value is None:
            return []
        if isinstance(value, (str, bytes)):
            return [value]
        if hasattr(value, "tolist"):
            try:
                converted = value.tolist()
                return converted if isinstance(converted, list) else [converted]
            except Exception:
                pass
        if isinstance(value, (list, tuple)):
            return list(value)
        try:
            iter(value)
        except TypeError:
            return [value]
        return list(value)

    def _materialize(item):
        if (
            isinstance(item, (list, tuple))
            and len(item) == 2
            and all(isinstance(x, int) for x in item)
        ):
            low, high = item
            return randint(low, high)
        return item

    def _pad(values, size):
        if size <= 0:
            return []
        if not values:
            return [0] * size
        if len(values) >= size:
            return values[:size]
        return values + [values[-1]] * (size - len(values))

    goals_list = [_materialize(v) for v in _to_list(goals)]
    penalties_list = [_materialize(v) for v in _to_list(penalties)]

    n_teams = max(len(goals_list), len(penalties_list))
    if n_teams == 0:
        return pd.DataFrame(columns=["Team", "Match Result"])

    goals_list = _pad(goals_list, n_teams)
    penalties_list = _pad(penalties_list, n_teams)

    teams = [f"Team {i + 1}" for i in range(n_teams)]
    match_results = [
        f"Goals: {g}, Penalties: {p}, Fine: {p * PREDEFINED_FINE_COST}"
        for g, p in zip(goals_list, penalties_list)
    ]

    return pd.DataFrame({"Team": teams, "Match Result": match_results})
