import struct
import zlib

# Constants
KEY = '470FC614'


def task_func(hex_string=KEY):
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a string")

    s = hex_string.strip()
    if s.lower().startswith("0x"):
        s = s[2:]

    if len(s) % 2 != 0:
        raise ValueError("hex_string must contain an even number of hex digits")

    try:
        raw = bytes.fromhex(s)
    except ValueError as exc:
        raise ValueError("hex_string must contain valid hexadecimal characters") from exc

    if len(raw) != 4:
        raise ValueError("hex_string must represent exactly 4 bytes for a binary32 float")

    float_value = struct.unpack(">f", raw)[0]
    binary32 = struct.pack(">f", float_value)
    compressed = zlib.compress(binary32)

    return {"bytes": compressed}
