    Count POS tags in a sentence, excluding the last word.

    Args:
        content: Input sentence as a string.

    Returns:
        dict: POS tag counts for all words except the last one.
    """
    if content is None:
        return {}

    text = str(content).strip()
    if not text:
        return {}

    try:
        tokens = nltk.word_tokenize(text)
    except LookupError:
        tokens = text.split()

    # Keep only word-like tokens and exclude the last word.
    words = [tok for tok in tokens if any(ch.isalnum() for ch in tok)]
    if len(words) <= 1:
        return {}

    words = words[:-1]

    try:
        tagged = nltk.pos_tag(words)
    except LookupError:
        # Ensure tagger resources are available if the environment needs the newer name.
        nltk.download('averaged_perceptron_tagger', quiet=True)
        nltk.download('averaged_perceptron_tagger_eng', quiet=True)
        tagged = nltk.pos_tag(words)

    return dict(Counter(tag for _, tag in tagged))
