def task_func(arr):
    """
    Reverse the order of parts in each string of a NumPy array,
    using '. ' as the primary separator and '.' as a fallback.
    """
    def reverse_parts(x):
        if not isinstance(x, str):
            return x
        if ". " in x:
            parts = x.split(". ")
            return ". ".join(parts[::-1])
        if "." in x:
            parts = x.split(".")
            return ".".join(parts[::-1])
        return x

    arr_np = np.asarray(arr)
    return np.vectorize(reverse_parts, otypes=[object])(arr_np)
