import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    error_message = None
    result = None

    try:
        save_dir = os.path.dirname(save_path)
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)

        os.makedirs(extract_path, exist_ok=True)

        with urllib.request.urlopen(url) as response, open(save_path, "wb") as zip_file:
            zip_file.write(response.read())

        with zipfile.ZipFile(save_path, "r") as zip_ref:
            zip_ref.extractall(extract_path)

        result = extract_path

    except urllib.error.URLError as exc:
        reason = getattr(exc, "reason", None)
        error_message = f"URL Error: {reason if reason is not None else exc}"

    except zipfile.BadZipFile:
        error_message = "ZIP Error: Invalid or corrupted ZIP file"

    except OSError as exc:
        error_message = f"File Error: {exc}"

    except Exception as exc:
        error_message = f"Error: {exc}"

    finally:
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError as cleanup_exc:
                if error_message is None:
                    error_message = f"File Error: {cleanup_exc}"
                    result = None

    if error_message is not None:
        return error_message

    return result if result is not None else extract_path
