                if os.path.isdir(dest_path):
                    shutil.rmtree(dest_path)
                else:
                    os.remove(dest_path)
            shutil.move(file_path, dest_path)

            frames.append(df_file)
        except (json.JSONDecodeError, ValueError, OSError, TypeError):
            continue

    if frames:
        df = pd.concat(frames, ignore_index=True)
    else:
