import regex as re
import glob
import os
from openpyxl import load_workbook


def task_func(directory_path='./xlsx_files/'):
    if not os.path.isdir(directory_path):
        return 0

    replacement = "\\\\" + '"'
    quote_pattern = re.compile(r'"')

    patterns = (
        os.path.join(directory_path, "*.xlsx"),
        os.path.join(directory_path, "*.XLSX"),
    )

    excel_files = []
    seen = set()
    for pattern in patterns:
        for path in glob.glob(pattern):
            if path in seen:
                continue
            if not os.path.isfile(path):
                continue
            if os.path.basename(path).startswith("~$"):
                continue
            seen.add(path)
            excel_files.append(path)

    processed_count = 0

    for file_path in excel_files:
        try:
            workbook = load_workbook(file_path)
        except Exception:
            continue

        try:
            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        value = cell.value
                        if cell.data_type != 'f' and isinstance(value, str) and '"' in value:
                            cell.value = quote_pattern.sub(lambda _m: replacement, value)

            workbook.save(file_path)
            processed_count += 1
        except Exception:
            continue
        finally:
            try:
                workbook.close()
            except Exception:
                pass

    return processed_count
