def task_func(goals, penalties, rng_seed=None):
    if rng_seed is not None:
        seed(rng_seed)

    def _as_list(value, name):
        if isinstance(value, Integral) and not isinstance(value, bool):
            if value < 0:
                raise ValueError(f"{name} must be non-negative")
            return [int(value)]
        if isinstance(value, (str, bytes)):
            raise TypeError(f"{name} must be an integer or an iterable of integers")
        try:
            return list(value)
        except TypeError as exc:
            raise TypeError(f"{name} must be an integer or an iterable of integers") from exc

    def _check_int(value, name):
        if not isinstance(value, Integral) or isinstance(value, bool):
            raise TypeError(f"all {name} values must be integers")
        if value < 0:
            raise ValueError(f"{name} values must be non-negative")
        return int(value)

    goals_list = _as_list(goals, "goals")
    penalties_list = _as_list(penalties, "penalties")

    if len(goals_list) != len(penalties_list):
        raise ValueError("goals and penalties must have the same length")

    rows = []
    for idx, (goal_limit, penalty_limit) in enumerate(zip(goals_list, penalties_list), start=1):
        goal_limit = _check_int(goal_limit, "goal")
        penalty_limit = _check_int(penalty_limit, "penalty")

        goals_scored = randint(0, goal_limit) if goal_limit > 0 else 0
        penalties_count = randint(0, penalty_limit) if penalty_limit > 0 else 0
        fine = penalties_count * PENALTY_COST

        rows.append(
            {
                "Team": f"Team {idx}",
                "Match Result": f"Goals: {goals_scored}, Penalties: {penalties_count}, Fine: {fine}",
            }
        )

    return pd.DataFrame(rows, columns=["Team", "Match Result"])
