import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    directory = Path(directory_path)
    if not directory.exists() or not directory.is_dir():
        return {}

    default_like_patterns = {r'\\(.+?\\)|\\w', r'\(.+?\)|\w'}
    result = {}

    for file_path in sorted((Path(p) for p in glob.glob(str(directory / "*"))), key=lambda p: p.name):
        if not file_path.is_file():
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        if regex_pattern in default_like_patterns:
            matches = []
            i = 0
            n = len(content)
            while i < n:
                if content[i] == "(":
                    closing = content.find(")", i + 1)
                    if closing != -1:
                        matches.append(content[i + 1:closing])
                        i = closing + 1
                        continue
                matches.append(content[i])
                i += 1
        else:
            try:
                compiled = re.compile(regex_pattern)
            except re.error:
                matches = []
            else:
                matches = []
                for match in compiled.finditer(content):
                    groups = match.groups()
                    if groups:
                        token = next((group for group in groups if group is not None), match.group(0))
                    else:
                        token = match.group(0)
                    matches.append(token)

        result[os.path.basename(str(file_path))] = matches

    return result
