import urllib.request
import zipfile
import os
import urllib.error

def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    def _safe_delete(path: str) -> None:
        try:
            if os.path.exists(path):
                os.remove(path)
        except OSError:
            pass

    try:
        # Ensure the extraction directory exists.
        os.makedirs(extract_path, exist_ok=True)

        # Download the ZIP file.
        try:
            with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
                out_file.write(response.read())
        except urllib.error.URLError as e:
            reason = getattr(e, "reason", e)
            return f"URL Error: {reason}"

        # Extract the ZIP file.
        try:
            with zipfile.ZipFile(save_path, "r") as zip_ref:
                zip_ref.extractall(extract_path)
        except zipfile.BadZipFile:
            return "Error: The downloaded file is not a valid ZIP archive or it is corrupted."
        except OSError as e:
            return f"File I/O Error: {e}"
        finally:
            # Delete the ZIP file after extraction attempt.
            _safe_delete(save_path)

        return extract_path

    except urllib.error.URLError as e:
        reason = getattr(e, "reason", e)
        return f"URL Error: {reason}"
    except zipfile.BadZipFile:
        _safe_delete(save_path)
        return "Error: The downloaded file is not a valid ZIP archive or it is corrupted."
    except OSError as e:
        _safe_delete(save_path)
        return f"File I/O Error: {e}"
    except Exception as e:
        _safe_delete(save_path)
        return f"Error: {e}"
