import shutil

def task_func(path):
    if not os.path.exists(path):
        os.makedirs(path, exist_ok=True)
    if not os.path.isdir(path):
        return pd.DataFrame()

    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    def _json_to_df(obj):
        if isinstance(obj, list):
            if obj and all(isinstance(item, dict) for item in obj):
                return pd.json_normalize(obj)
            return pd.DataFrame(obj)
        if isinstance(obj, dict):
            return pd.json_normalize(obj)
        return pd.DataFrame([obj])

    frames = []

    for filename in sorted(os.listdir(path)):
        filepath = os.path.join(path, filename)
        if not filename.lower().endswith(".json") or not os.path.isfile(filepath):
            continue

        try:
            with open(filepath, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception:
            continue

        df = _json_to_df(data)

        if "Source" in df.columns:
            df["Source"] = filename
            cols = ["Source"] + [c for c in df.columns if c != "Source"]
            df = df[cols]
        else:
            df.insert(0, "Source", filename)

        frames.append(df)

        target_path = os.path.join(processed_dir, filename)
        if os.path.exists(target_path):
            if os.path.isdir(target_path):
                shutil.rmtree(target_path)
            else:
                os.remove(target_path)
        shutil.move(filepath, target_path)

    if frames:
        return pd.concat(frames, ignore_index=True)
    return pd.DataFrame()
