import os
from pathlib import Path
import pandas as pd
import docx


def _extract_txt_or_csv_text(file_path: Path) -> str:
    return file_path.read_text(encoding="utf-8", errors="replace")


def _extract_docx_text(file_path: Path) -> str:
    document = docx.Document(str(file_path))
    parts = []

    for paragraph in document.paragraphs:
        if paragraph.text:
            parts.append(paragraph.text)

    for table in document.tables:
        for row in table.rows:
            row_text = [cell.text for cell in row.cells if cell.text]
            if row_text:
                parts.append("\t".join(row_text))

    return "\n".join(parts)


def _extract_xlsx_text(file_path: Path) -> str:
    excel_file = pd.ExcelFile(file_path)
    parts = []

    for sheet_name in excel_file.sheet_names:
        df = excel_file.parse(sheet_name=sheet_name)
        df = df.fillna("")
        parts.append(f"Sheet: {sheet_name}")
        parts.append(df.to_csv(index=False))

    return "\n".join(parts).strip()


def _write_single_column_csv(text: str, output_path: Path) -> None:
    pd.DataFrame({"Text": [text]}).to_csv(output_path, index=False)


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    target_path = Path(target_directory)

    if not source_path.is_dir():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")

    target_path.mkdir(parents=True, exist_ok=True)

    supported_extensions = {".txt", ".docx", ".xlsx", ".csv"}
    converted_count = 0

    for file_path in sorted(source_path.iterdir()):
        if not file_path.is_file():
            continue

        suffix = file_path.suffix.lower()
        if suffix not in supported_extensions:
            continue

        if suffix in {".txt", ".csv"}:
            text_content = _extract_txt_or_csv_text(file_path)
        elif suffix == ".docx":
            text_content = _extract_docx_text(file_path)
        elif suffix == ".xlsx":
            text_content = _extract_xlsx_text(file_path)
        else:
            continue

        output_file = target_path / f"{file_path.stem}.csv"
        _write_single_column_csv(text_content, output_file)
        converted_count += 1

    return converted_count
